        "display": false,
        "benches": [
          {
            "name": "The speed of refill-replace on Linux (Ramfs)",
            "value": "3.624",
            "unit": "second",
            "extra": "linux_result"
          },
          {
            "name": "The speed of refill-replace on Asterinas (Ramfs)",
            "value": "4.244",
            "unit": "second",
            "extra": "aster_result"
          }
        ]
